Contract GenerateLoanLetterAndAgreementModule::genereateApprovalLetter(id:Integer): Boolean {
          definition:
          let newApprovalLetter: ApprovalLetter in let loanRequest: LoanRequest = LoanRequest.allInstance()->any(o | o.RequestID = id)

            precondition:
          let loanRequest: LoanRequest = LoanRequest.allInstance()->any(o | o.RequestID = id) in not loanRequest.oclIsUndefined()

            postcondition:
          newApprovalLetter.oclIsNew() and newApprovalLetter.Content = "ApprovalLetterContent" and ApprovalLetter.allInstance()->includes(newApprovalLetter) and loanRequest.AttachedApprovalLetter = newApprovalLetter and CurrentLoanRequest = loanRequest and result = true

        }
